export class PayoutNotification {
    id;
    remittanceReference;
    status;
    amount;
    currencyCode;
    constructor(payout) {
        this.id = payout.id;
        this.remittanceReference = payout.remittance_reference;
        this.status = payout.status;
        this.amount = payout.amount;
        this.currencyCode = payout.currency_code;
    }
}
